// ✅ Dùng renderHook & act từ @testing-library/react
import { renderHook, act } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import { useCounter } from './useCounter';

describe('useCounter', () => {
  it('khởi tạo giá trị mặc định và tăng đếm chính xác', () => {
    const { result } = renderHook(() => useCounter(10));

    expect(result.current.count).toBe(10);

    act(() => {
      result.current.increment();
    });

    expect(result.current.count).toBe(11);
  });
});

// ✅ Chuẩn Accessible Modal & Kháng lỗi
import React, { useEffect, useRef } from 'react';

interface AccessibleModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

export function AccessibleModal({ isOpen, onClose, title, children }: AccessibleModalProps) {
  const dialogRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    if (isOpen) window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm"
    >
      <div ref={dialogRef} className="w-full max-w-lg rounded-2xl bg-card p-6 shadow-2xl">
        <h2 id="modal-title" className="text-lg font-bold">{title}</h2>
        <div className="py-4">{children}</div>
        <button onClick={onClose} aria-label="Đóng hộp thoại" className="mt-2 rounded-lg bg-primary px-4 py-2 text-primary-foreground">
          Đóng
        </button>
      </div>
    </div>
  );
}

